import argparse
import sys
from datetime import datetime

from .events import count_events, events_since, read_events, to_utc


def parse_since(value):
    """Parse a --since value (a date like 2024-03-10, or an ISO timestamp) into aware UTC."""
    try:
        ts = datetime.fromisoformat(value)
    except ValueError:
        raise argparse.ArgumentTypeError(
            f"invalid date {value!r}: expected YYYY-MM-DD or an ISO 8601 timestamp, e.g. 2024-03-10"
        ) from None
    return to_utc(ts)


def build_parser():
    parser = argparse.ArgumentParser(prog="evlog")
    commands = parser.add_subparsers(dest="command", required=True)
    report = commands.add_parser("report", help="count events per service and level")
    report.add_argument("path", help="events file (JSON lines)")
    report.add_argument(
        "--since",
        type=parse_since,
        metavar="DATE",
        help="only count events at or after this date (UTC midnight); naive timestamps are UTC",
    )
    return parser


def render(counts):
    lines = [f"{service} {level} {n}" for (service, level), n in sorted(counts.items())]
    lines.append(f"total {sum(counts.values())}")
    return "\n".join(lines)


def main(argv=None, out=None):
    out = out or sys.stdout
    args = build_parser().parse_args(argv)
    if args.command == "report":
        counts = count_events(read_events(args.path))
        print(render(counts), file=out)
    return 0

import argparse
import sys
from datetime import datetime

from .events import count_events, events_since, read_events, to_utc


def parse_since(value):
    """Parse a --since value (a date like 2024-03-10, or an ISO timestamp) into aware UTC."""
    try:
        ts = datetime.fromisoformat(value)
    except ValueError:
        raise argparse.ArgumentTypeError(
            f"invalid date {value!r}: expected YYYY-MM-DD or an ISO 8601 timestamp, e.g. 2024-03-10"
        ) from None
    return to_utc(ts)


def build_parser():
    parser = argparse.ArgumentParser(prog="evlog")
    commands = parser.add_subparsers(dest="command", required=True)
    report = commands.add_parser("report", help="count events per service and level")
    report.add_argument("path", help="events file (JSON lines)")
    report.add_argument(
        "--since",
        type=parse_since,
        metavar="DATE",
        help="only count events at or after this date (UTC midnight); naive timestamps are UTC",
    )
    return parser


def render(counts):
    lines = [f"{service} {level} {n}" for (service, level), n in sorted(counts.items())]
    lines.append(f"total {sum(counts.values())}")
    return "\n".join(lines)


def main(argv=None, out=None):
    out = out or sys.stdout
    args = build_parser().parse_args(argv)
    if args.command == "report":
        events = read_events(args.path)
        if args.since is not None:
            events = events_since(events, args.since)
        counts = count_events(events)
        print(render(counts), file=out)
